import React from 'react';
import { 
  PlayIcon, PauseIcon, MuteIcon, UnmuteIcon, TranscriptIcon, 
  SpeedIcon, CCIcon, FullscreenIcon, PiPIcon, VolumeIcon, 
  AudioDescIcon, ChaptersIcon, SettingsIcon, InfoIcon, QualityIcon,
  LinkIcon // NEU
} from './icons';
import styles from './PlayerControls.module.css';


interface PlayerControlsBaseProps {
  playerState: any;
  playerControls: any;
}

interface PlayerControlsFullProps extends PlayerControlsBaseProps {
  hasCC: boolean;
  hasTranscript: boolean;
  hasAudioDesc: boolean;
  hasChapters: boolean;
}

interface PlayerControlsMinimalProps extends PlayerControlsBaseProps {
  onFullPlayerClick?: () => void;
}

// FULL PLAYER CONTROLS
export const PlayerControlsFull: React.FC<PlayerControlsFullProps> = ({
  playerState,
  playerControls,
  hasCC,
  hasTranscript,
  hasAudioDesc,
  hasChapters
}) => {
  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  return (
    <div className={styles.fullControlsContainer}>
      {/* Progress Bar */}
      <div className={styles.progressBar}>
        <span className={styles.timeDisplay}>
          {formatTime(playerState.currentTime)}
        </span>
        <input
          type="range"
          min={0}
          max={playerState.duration || 1}
          step={0.01}
          value={playerState.currentTime}
          onChange={e => playerControls.handleSeek(Number(e.target.value))}
          aria-label="Fortschritt"
          className={styles.progressSlider}
        />
        <span className={styles.timeDisplay}>
          {formatTime(playerState.duration)}
        </span>
      </div>

      {/* First Row Controls */}
      <div className={styles.controlsRow}>
        <div className={styles.leftControls}>
          <button
            onClick={(e) => {
              e.stopPropagation();
              playerState.isPlaying ? playerControls.handlePause() : playerControls.handlePlay();
            }}
            className={`${styles.controlButton} ${styles.playPauseButton} ${
              playerState.isPlaying ? styles.active : styles.inactive
            }`}
            aria-label={playerState.isPlaying ? 'Pausieren' : 'Abspielen'}
          >
            {playerState.isPlaying ? <PauseIcon /> : <PlayIcon />}
          </button>

          <button
            onClick={(e) => {
              e.stopPropagation();
              playerControls.handleMuteToggle();
            }}
            className={`${styles.controlButton} ${
              !playerState.isMuted ? styles.active : styles.inactive
            }`}
            aria-label={playerState.isMuted ? 'Ton an' : 'Stumm'}
          >
            {playerState.isMuted ? <UnmuteIcon /> : <MuteIcon />}
          </button>

          <button
            onClick={(e) => {
              e.stopPropagation();
              playerControls.handleSeek(playerState.currentTime - 10);
            }}
            className={`${styles.controlButton} ${styles.neutral}`}
            aria-label="10 Sekunden zurück"
          >
            ⏪
          </button>

          <button
            onClick={(e) => {
              e.stopPropagation();
              playerControls.handleSeek(playerState.currentTime + 10);
            }}
            className={`${styles.controlButton} ${styles.neutral}`}
            aria-label="10 Sekunden vor"
          >
            ⏩
          </button>
        </div>

        <div className={styles.rightControls}>
          {playerState.isPiPSupported && (
            <button
              onClick={(e) => {
                e.stopPropagation();
                playerControls.handlePiP();
              }}
              className={`${styles.controlButton} ${styles.neutral}`}
              aria-label="Bild-in-Bild"
            >
              <PiPIcon />
            </button>
          )}

          <button
            onClick={(e) => {
              e.stopPropagation();
              playerControls.handleFullscreen();
            }}
            className={`${styles.controlButton} ${styles.neutral}`}
            aria-label="Vollbild"
          >
            <FullscreenIcon />
          </button>
        </div>
      </div>

      {/* Second Row Controls */}
      <div className={styles.controlsRow}>
        <div className={styles.leftControls}>
          <button 
            className={`${styles.controlButton} ${styles.neutral}`}
            aria-label="Qualität"
          >
            <QualityIcon />
          </button>

          <button 
            className={`${styles.controlButton} ${styles.neutral}`}
            aria-label="Einstellungen"
          >
            <SettingsIcon />
          </button>

          {hasCC && (
            <button
              onClick={(e) => {
                e.stopPropagation();
                playerState.setShowCC(!playerState.showCC);
              }}
              className={`${styles.controlButton} ${
                playerState.showCC ? styles.active : styles.inactive
              }`}
              aria-label="Untertitel"
            >
              <CCIcon />
            </button>
          )}

          {hasTranscript && (
            <button 
              onClick={() => playerState.setShowTranscript(!playerState.showTranscript)} 
              className={`${styles.controlButton} ${
                playerState.showTranscript ? styles.active : styles.inactive
              }`}
              aria-label="Transkript anzeigen/verbergen"
            >
              <TranscriptIcon />
            </button>
          )}

          {hasAudioDesc && (
            <button
              onClick={() => playerState.setAudioDescSettingsOpen(true)}
              className={`${styles.controlButton} ${
                playerState.audioDescActive ? styles.active : styles.inactive
              }`}
              aria-label="Audiodeskription Einstellungen"
            >
              <AudioDescIcon />
            </button>
          )}

          {hasChapters && (
            <button 
              onClick={() => playerState.setShowChapters(!playerState.showChapters)} 
              className={`${styles.controlButton} ${
                playerState.showChapters ? styles.active : styles.inactive
              }`}
              aria-label="Kapitel anzeigen/verbergen"
            >
              <ChaptersIcon />
            </button>
          )}
        </div>
      </div>
    </div>
  );
};

// MINIMAL PLAYER CONTROLS
export const PlayerControlsMinimal: React.FC<PlayerControlsMinimalProps> = ({
  playerState,
  playerControls,
  onFullPlayerClick
}) => {
  return (
    <div className={styles.minimalControlsContainer}>
      <button
        onClick={(e) => {
          e.stopPropagation();
          playerState.isPlaying ? playerControls.handlePause() : playerControls.handlePlay();
        }}
        className={`${styles.controlButton} ${styles.playPauseButton} ${
          playerState.isPlaying ? styles.active : styles.inactive
        }`}
        aria-label={playerState.isPlaying ? 'Pausieren' : 'Abspielen'}
      >
        {playerState.isPlaying ? <PauseIcon /> : <PlayIcon />}
      </button>

      <button
        onClick={(e) => {
          e.stopPropagation();
          playerControls.handleMuteToggle();
        }}
        className={`${styles.controlButton} ${
          !playerState.isMuted ? styles.active : styles.inactive
        }`}
        aria-label={playerState.isMuted ? 'Ton an' : 'Stumm'}
      >
        {playerState.isMuted ? <UnmuteIcon /> : <MuteIcon />}
      </button>

      <div className={styles.spacer} />

      <button
        onClick={(e) => {
          e.stopPropagation();
          onFullPlayerClick?.();
        }}
        className={`${styles.controlButton} ${styles.neutral}`}
        aria-label="Vollständiger Player"
      >
        <LinkIcon />
      </button>
    </div>
  );
};

// LEGACY EXPORT für Kompatibilität
export const PlayerControls: React.FC<PlayerControlsFullProps> = PlayerControlsFull;