import React, { useCallback } from 'react';

interface UsePlayerControlsProps {
  videoRef: React.RefObject<HTMLVideoElement | null>; // FIXED - null erlaubt
  youtubeContainerRef: React.RefObject<HTMLDivElement | null>; // FIXED - null erlaubt  
  vimeoContainerRef: React.RefObject<HTMLDivElement | null>; // FIXED - null erlaubt
  playerState: any;
}

export const usePlayerControls = ({ 
  videoRef, 
  youtubeContainerRef, 
  vimeoContainerRef, 
  playerState 
}: UsePlayerControlsProps) => {
  
  const handlePlay = useCallback(() => {
    if (videoRef.current) {
      videoRef.current.play();
      playerState.setIsPlaying(true);
    }
  }, [playerState, videoRef]);

  const handlePause = useCallback(() => {
    if (videoRef.current) {
      videoRef.current.pause();
      playerState.setIsPlaying(false);
    }
  }, [playerState, videoRef]);
 
  const handleSeek = useCallback((time: number) => {
    if (videoRef.current) {
      videoRef.current.currentTime = time;
      playerState.setCurrentTime(time);
    }
  }, [playerState, videoRef]);

  const handleMuteToggle = useCallback(() => {
    if (videoRef.current) {
      const newMuted = !playerState.isMuted;
      videoRef.current.muted = newMuted;
      playerState.setIsMuted(newMuted);
    }
  }, [playerState, videoRef]);

  const handleFullscreen = useCallback(() => {
    if (videoRef.current?.requestFullscreen) {
      videoRef.current.requestFullscreen();
    }
  }, [videoRef]);

  const handlePiP = useCallback(() => {
    if (videoRef.current && (videoRef.current as any).requestPictureInPicture) {
      (videoRef.current as any).requestPictureInPicture();
    }
  }, [videoRef]);

  const handleChapterClick = useCallback((time: number) => {
    handleSeek(time);
  }, [handleSeek]);

  return {
    handlePlay,
    handlePause,
    handleSeek,
    handleMuteToggle,
    handleFullscreen,
    handlePiP,
    handleChapterClick
  };
};